import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import math
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# HIP kernel for fused delta rule recurrence
deltanet_kernel_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

// Fused kernel for GatedDeltaNet recurrence
// S_t = alpha_t * S_{t-1} - beta_t * (S_{t-1} @ k_t - v_t) @ k_t^T
// o_t = S_t @ q_t
// 
// Each block handles one (batch, head) pair
// Threads within a block cooperate on the state matrix operations

__global__ void gated_deltanet_recurrence_kernel(
    const float* __restrict__ q,      // [batch, seq_len, num_heads, head_dim_qk]
    const float* __restrict__ k,      // [batch, seq_len, num_heads, head_dim_qk]
    const float* __restrict__ v,      // [batch, seq_len, num_heads, head_dim_v]
    const float* __restrict__ alpha,  // [batch, seq_len, num_heads]
    const float* __restrict__ beta,   // [batch, seq_len, num_heads]
    float* __restrict__ output,       // [batch, seq_len, num_heads, head_dim_v]
    int batch_size,
    int seq_len,
    int num_heads,
    int head_dim_qk,
    int head_dim_v
) {
    // Each block handles one (batch, head) pair
    int batch_idx = blockIdx.x / num_heads;
    int head_idx = blockIdx.x % num_heads;

    if (batch_idx >= batch_size) return;

    int tid = threadIdx.x;
    int num_threads = blockDim.x;

    // State matrix S: [head_dim_v, head_dim_qk]
    // Each thread handles a subset of the state matrix elements
    extern __shared__ float shared_mem[];
    float* S = shared_mem;  // [head_dim_v * head_dim_qk]
    float* S_k = S + head_dim_v * head_dim_qk;  // [head_dim_v] - result of S @ k
    float* k_shared = S_k + head_dim_v;  // [head_dim_qk]
    float* v_shared = k_shared + head_dim_qk;  // [head_dim_v]
    float* q_shared = v_shared + head_dim_v;  // [head_dim_qk]

    int state_size = head_dim_v * head_dim_qk;

    // Initialize state to zero
    for (int i = tid; i < state_size; i += num_threads) {
        S[i] = 0.0f;
    }
    __syncthreads();

    // Loop over sequence
    for (int t = 0; t < seq_len; t++) {
        // Load k, v, q for this timestep
        int base_qk = ((batch_idx * seq_len + t) * num_heads + head_idx) * head_dim_qk;
        int base_v = ((batch_idx * seq_len + t) * num_heads + head_idx) * head_dim_v;
        int base_gate = (batch_idx * seq_len + t) * num_heads + head_idx;

        // Load k into shared memory
        for (int i = tid; i < head_dim_qk; i += num_threads) {
            k_shared[i] = k[base_qk + i];
        }
        // Load v into shared memory
        for (int i = tid; i < head_dim_v; i += num_threads) {
            v_shared[i] = v[base_v + i];
        }
        // Load q into shared memory
        for (int i = tid; i < head_dim_qk; i += num_threads) {
            q_shared[i] = q[base_qk + i];
        }
        __syncthreads();

        float alpha_t = alpha[base_gate];
        float beta_t = beta[base_gate];

        // Compute S @ k -> S_k [head_dim_v]
        // Each thread computes some rows
        for (int i = tid; i < head_dim_v; i += num_threads) {
            float sum = 0.0f;
            for (int j = 0; j < head_dim_qk; j++) {
                sum += S[i * head_dim_qk + j] * k_shared[j];
            }
            S_k[i] = sum;
        }
        __syncthreads();

        // Compute error = S_k - v and update S
        // S_ij = alpha * S_ij - beta * error_i * k_j
        // where error_i = S_k_i - v_i
        for (int idx = tid; idx < state_size; idx += num_threads) {
            int i = idx / head_dim_qk;  // v dimension
            int j = idx % head_dim_qk;  // k dimension

            float error_i = S_k[i] - v_shared[i];
            S[idx] = alpha_t * S[idx] - beta_t * error_i * k_shared[j];
        }
        __syncthreads();

        // Compute output: o = S @ q -> [head_dim_v]
        int out_base = ((batch_idx * seq_len + t) * num_heads + head_idx) * head_dim_v;
        for (int i = tid; i < head_dim_v; i += num_threads) {
            float sum = 0.0f;
            for (int j = 0; j < head_dim_qk; j++) {
                sum += S[i * head_dim_qk + j] * q_shared[j];
            }
            output[out_base + i] = sum;
        }
        __syncthreads();
    }
}

torch::Tensor gated_deltanet_recurrence(
    torch::Tensor q,
    torch::Tensor k,
    torch::Tensor v,
    torch::Tensor alpha,
    torch::Tensor beta
) {
    int batch_size = q.size(0);
    int seq_len = q.size(1);
    int num_heads = q.size(2);
    int head_dim_qk = q.size(3);
    int head_dim_v = v.size(3);

    auto output = torch::zeros({batch_size, seq_len, num_heads, head_dim_v}, 
                               q.options());

    // Ensure contiguous
    q = q.contiguous();
    k = k.contiguous();
    v = v.contiguous();
    alpha = alpha.contiguous();
    beta = beta.contiguous();

    int num_blocks = batch_size * num_heads;
    int threads_per_block = 256;

    // Shared memory: S + S_k + k + v + q
    int shared_mem_size = (head_dim_v * head_dim_qk + head_dim_v + head_dim_qk + head_dim_v + head_dim_qk) * sizeof(float);

    hipLaunchKernelGGL(gated_deltanet_recurrence_kernel, 
                       dim3(num_blocks), dim3(threads_per_block), shared_mem_size, 0,
                       q.data_ptr<float>(),
                       k.data_ptr<float>(),
                       v.data_ptr<float>(),
                       alpha.data_ptr<float>(),
                       beta.data_ptr<float>(),
                       output.data_ptr<float>(),
                       batch_size, seq_len, num_heads, head_dim_qk, head_dim_v);

    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("gated_deltanet_recurrence", &gated_deltanet_recurrence, "Gated DeltaNet recurrence");
}
"""

deltanet_module = load_inline(
    name="gated_deltanet_hip",
    cpp_sources="",
    cuda_sources=deltanet_kernel_source,
    functions=["gated_deltanet_recurrence"],
    verbose=True,
    extra_cuda_cflags=["-O3"]
)


class ModelNew(nn.Module):
    """
    Optimized Gated DeltaNet with fused HIP kernel for recurrence.
    """

    def __init__(
        self,
        hidden_size: int,
        num_heads: int,
        head_dim_qk: int,
        head_dim_v: int,
        use_short_conv: bool = True,
        conv_kernel_size: int = 4,
    ):
        super().__init__()
        self.hidden_size = hidden_size
        self.num_heads = num_heads
        self.head_dim_qk = head_dim_qk
        self.head_dim_v = head_dim_v
        self.use_short_conv = use_short_conv

        # Q, K, V projections
        self.q_proj = nn.Linear(hidden_size, num_heads * head_dim_qk, bias=False)
        self.k_proj = nn.Linear(hidden_size, num_heads * head_dim_qk, bias=False)
        self.v_proj = nn.Linear(hidden_size, num_heads * head_dim_v, bias=False)

        # Gating projections
        self.a_proj = nn.Linear(hidden_size, num_heads, bias=True)
        self.b_proj = nn.Linear(hidden_size, num_heads, bias=True)

        # Output projection
        self.o_proj = nn.Linear(num_heads * head_dim_v, hidden_size, bias=False)

        # Optional short convolution for local context
        if use_short_conv:
            self.q_conv = nn.Conv1d(
                num_heads * head_dim_qk, num_heads * head_dim_qk,
                kernel_size=conv_kernel_size, groups=num_heads * head_dim_qk,
                padding=conv_kernel_size - 1
            )
            self.k_conv = nn.Conv1d(
                num_heads * head_dim_qk, num_heads * head_dim_qk,
                kernel_size=conv_kernel_size, groups=num_heads * head_dim_qk,
                padding=conv_kernel_size - 1
            )
            self.v_conv = nn.Conv1d(
                num_heads * head_dim_v, num_heads * head_dim_v,
                kernel_size=conv_kernel_size, groups=num_heads * head_dim_v,
                padding=conv_kernel_size - 1
            )

        # Output gate with RMSNorm + SiLU
        self.g_proj = nn.Linear(hidden_size, num_heads * head_dim_v, bias=False)
        self.o_norm = nn.LayerNorm(head_dim_v)

        # Scaling factor for keys
        self.scale = head_dim_qk ** -0.5

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        batch_size, seq_len, _ = x.shape

        # Project to Q, K, V
        q = self.q_proj(x)
        k = self.k_proj(x)
        v = self.v_proj(x)

        # Optional short convolution
        if self.use_short_conv:
            q = self.q_conv(q.transpose(1, 2))[:, :, :seq_len].transpose(1, 2)
            k = self.k_conv(k.transpose(1, 2))[:, :, :seq_len].transpose(1, 2)
            v = self.v_conv(v.transpose(1, 2))[:, :, :seq_len].transpose(1, 2)
            q = F.silu(q)
            k = F.silu(k)
            v = F.silu(v)

        # Reshape for multi-head attention
        q = q.view(batch_size, seq_len, self.num_heads, self.head_dim_qk)
        k = k.view(batch_size, seq_len, self.num_heads, self.head_dim_qk)
        v = v.view(batch_size, seq_len, self.num_heads, self.head_dim_v)

        # Compute gating values
        alpha = torch.sigmoid(self.a_proj(x))  # (batch, seq, num_heads)
        beta = torch.sigmoid(self.b_proj(x))   # (batch, seq, num_heads)

        # Scale keys
        k = k * self.scale

        # Use fused HIP kernel for recurrence
        o = deltanet_module.gated_deltanet_recurrence(q, k, v, alpha, beta)

        # Apply output normalization per head
        o = self.o_norm(o)

        # Apply output gate
        g = torch.sigmoid(self.g_proj(x))
        g = g.view(batch_size, seq_len, self.num_heads, self.head_dim_v)
        o = o * g

        # Reshape and project output
        o = o.reshape(batch_size, seq_len, self.num_heads * self.head_dim_v)
        o = self.o_proj(o)

        return o


def custom_kernel(inputs):
    x = inputs[0]
    batch_size = x.size(0)
    hidden_size = x.size(2)
    num_heads = 16
    head_dim_qk = 128
    head_dim_v = 128

    model = ModelNew(hidden_size, num_heads, head_dim_qk, head_dim_v).cuda()
    model.eval()

    with torch.no_grad():
        return model(x)

